def _caught(a):
    return a["crisis"] or a["text_risk"] >= 50 or bool(a.get("scam")) or bool(a.get("disaster")) or bool(a.get("intl_urgent"))


@pytest.mark.parametrize("t", DANGER)
def test_danger_is_caught(t):
    assert _caught(assess(t)), t


@pytest.mark.parametrize("t", BENIGN)
def test_benign_is_calm(t):
    assert not _caught(assess(t)), t


@pytest.mark.parametrize("t", ["หนังสือหล่นทับหัวลูก ไม่รู้สึกตัว", "ข่าวเรือล่ม มีคนหมดสติ ช่วยด้วย", "แม่ค้าหมดสติกลางตลาด"])
def test_severe_symptoms_are_never_calmed(t):
    """คำว่า หนังสือ / ข่าว ปนอยู่ ห้ามลดเรื่องที่มีคนหมดสติจริง"""
    assert _caught(assess(t)), t


@pytest.mark.parametrize("t", ["โดนต่อหัวเสือต่อยหลายสิบตัว", "โดนแมงป่องต่อย ชาไปทั้งแขน"])
def test_insect_stings_are_first_aid_not_assault(t):
    """"ต่อย" แปลว่าทั้งต่อยตีและแมลงต่อย — เดิมแมลงต่อยได้คำตอบความรุนแรง ส่งไปแจ้งตำรวจ"""
    a = assess(t)
    assert "violence" not in a["topics"] and a["text_risk"] >= 50


@pytest.mark.parametrize("t", ["โดนแฟนต่อยหน้า", "โดนคนต่อยที่ร้านเหล้า"])
def test_people_punching_is_still_violence(t):
    assert "violence" in assess(t)["topics"]
